"""REQ-357: the leaderboard page is generated by a script from result JSONs only; no
hand-edited numbers.

The committed page and report (``docs/benchmark/``) are regenerated from the committed
result files and must be byte-identical; a result edited by hand (signature no longer
matching) is refused; the page depends on nothing but the results.
"""

import json
import re
import shutil
import subprocess
import sys

import pytest

from evoparam.benchmark import leaderboard_html, load_results, write_leaderboard, write_report
from evoparam.benchmark.report import format_metric
from evoparam.benchmark.scoring import HEADLINE
from evoparam.errors import DataError

from .helpers import DOCS, RESULTS, ROOT


def test_req357_committed_page_and_report_come_from_the_results(tmp_path):
    page = write_leaderboard(str(RESULTS), str(tmp_path / "leaderboard.html"))
    report = write_report(str(RESULTS), str(tmp_path / "report.md"))
    assert open(page, "rb").read() == (DOCS / "leaderboard.html").read_bytes()
    assert open(report, "rb").read() == (DOCS / "report-core.md").read_bytes()


def test_req357_the_script_checks_the_committed_files():
    proc = subprocess.run([sys.executable, str(ROOT / "tools" / "benchmark_leaderboard.py"),
                           "--check"], capture_output=True, text=True, check=False)
    assert proc.returncode == 0, proc.stdout + proc.stderr
    assert "leaderboard: ok" in proc.stdout


def test_req357_the_script_finds_a_stale_page(tmp_path):
    page = tmp_path / "leaderboard.html"
    page.write_text((DOCS / "leaderboard.html").read_text(encoding="utf-8")
                    .replace("<td>0.", "<td>1.", 1), encoding="utf-8")
    proc = subprocess.run([sys.executable, str(ROOT / "tools" / "benchmark_leaderboard.py"),
                           "--check", "--page", str(page), "--report",
                           str(DOCS / "report-core.md")],
                          capture_output=True, text=True, check=False)
    assert proc.returncode == 1
    assert "not up to date" in proc.stdout


def test_req357_a_hand_edited_result_is_refused(tmp_path):
    folder = tmp_path / "results"
    shutil.copytree(RESULTS, folder)
    path = folder / "vanblooijs2023__T1.json"
    document = json.loads(path.read_text(encoding="utf-8"))
    document["headline"]["auc"] = 0.999
    path.write_text(json.dumps(document, indent=1, sort_keys=True), encoding="utf-8")
    with pytest.raises(DataError, match="signature does not match"):
        write_leaderboard(str(folder), str(tmp_path / "page.html"))
    assert not (tmp_path / "page.html").exists()


def test_req357_page_depends_only_on_the_results(tmp_path):
    """The same result files, in another folder, copied in another order: the same bytes;
    one result fewer: that row is gone."""

    folder = tmp_path / "copy"
    folder.mkdir()
    for path in sorted(RESULTS.glob("*.json"), reverse=True):
        shutil.copyfile(path, folder / path.name)
    page = write_leaderboard(str(folder), str(tmp_path / "page.html"))
    assert open(page, "rb").read() == (DOCS / "leaderboard.html").read_bytes()
    (folder / "keller2014__T1.json").unlink()
    text = leaderboard_html(load_results(str(folder)))
    t1 = text.split('<h2 id="T1">')[1].split("</table>")[0]
    assert "keller2014" not in t1


def test_req357_every_number_on_the_page_comes_from_a_result():
    docs = load_results(str(RESULTS))
    text = (DOCS / "leaderboard.html").read_text(encoding="utf-8")
    allowed = set()
    for d in docs:
        allowed |= {format_metric(h, d["headline"].get(h)) for h in HEADLINE[d["task"]]}
    cells = re.findall(r"<td>([^<]*)</td>", text)
    assert cells and set(cells) <= allowed
    for d in docs:
        assert d["signature"]["digest"][:12] in text
    assert "<script" not in text and "src=" not in text and "http" not in text.split(
        "</head>")[0].replace("http-equiv", "")


def test_req353_report_holds_rules_and_projection_t1_t2():
    """REQ-353 (also): the six published rules and the cross-projection test are in the
    first report, for T1 and T2 on the simulated core suite."""

    report = (DOCS / "report-core.md").read_text(encoding="utf-8")
    t1 = report.split("## T1")[1].split("## T2")[0]
    t2 = report.split("## T2")[1].split("## T3")[0]
    for name in ("vanblooijs2023", "hays2021", "keller2014", "silverstein2020", "ftract",
                 "prime2020", "projection"):
        assert f"| {name} |" in t1 and f"| {name} |" in t2, name
    assert "suite `core` 1.0.0" in report
